TRANSPORT = '#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport base64\nimport hashlib\nimport os\nimport shlex\nimport shutil\nimport stat\nimport subprocess\nimport tempfile\nfrom pathlib import Path\nfrom typing import Sequence\n\n\nclass SSHTransportError(RuntimeError):\n    pass\n\n\nclass Runner:\n    def run(\n        self,\n        argv: Sequence[str],\n        *,\n        timeout: float,\n        interactive: bool = False,\n        check: bool = True,\n    ) -> subprocess.CompletedProcess[str]:\n        command = tuple(argv)\n        try:\n            return subprocess.run(\n                command,\n                check=check,\n                text=True,\n                stdin=None if interactive else subprocess.DEVNULL,\n                stdout=None if interactive else subprocess.PIPE,\n                stderr=None if interactive else subprocess.PIPE,\n                timeout=timeout,\n            )\n        except subprocess.TimeoutExpired as error:\n            raise SSHTransportError(\n                f"command_timeout:{Path(command[0]).name}"\n            ) from error\n        except subprocess.CalledProcessError as error:\n            raise SSHTransportError(\n                f"command_failed:{Path(command[0]).name}:{error.returncode}"\n            ) from error\n        except OSError as error:\n            raise SSHTransportError(\n                f"command_transport_error:{Path(command[0]).name}"\n            ) from error\n\n\ndef _sha256_bytes(value: bytes) -> str:\n    return hashlib.sha256(value).hexdigest()\n\n\ndef _host_name(target: str) -> str:\n    return target.rsplit("@", 1)[-1]\n\n\ndef known_host_key_sha256(path: Path, target: str) -> str:\n    if path.is_symlink() or not path.is_file():\n        raise SSHTransportError("known_hosts_invalid")\n    metadata = path.stat()\n    if metadata.st_uid != os.geteuid() or stat.S_IMODE(metadata.st_mode) & 0o022:\n        raise SSHTransportError("known_hosts_metadata_invalid")\n    expected = _host_name(target)\n    matches: list[str] = []\n    for raw in path.read_text(encoding="utf-8").splitlines():\n        line = raw.strip()\n        if not line or line.startswith("#") or line.startswith("|"):\n            continue\n        fields = line.split()\n        if len(fields) < 3 or expected not in fields[0].split(","):\n            continue\n        try:\n            blob = base64.b64decode(fields[2], validate=True)\n        except ValueError as error:\n            raise SSHTransportError("known_hosts_key_invalid") from error\n        matches.append(_sha256_bytes(blob))\n    if len(matches) != 1:\n        raise SSHTransportError("known_hosts_target_binding_invalid")\n    return matches[0]\n\n\nclass SSHTransport:\n    def __init__(\n        self,\n        *,\n        target: str,\n        known_hosts: Path,\n        expected_host_key_sha256: str,\n        runner: Runner | None = None,\n        work_root: Path | None = None,\n    ) -> None:\n        if not target or any(character.isspace() for character in target):\n            raise SSHTransportError("target_invalid")\n        if (\n            len(expected_host_key_sha256) != 64\n            or any(\n                character not in "0123456789abcdef"\n                for character in expected_host_key_sha256\n            )\n        ):\n            raise SSHTransportError("host_key_sha256_invalid")\n        observed = known_host_key_sha256(known_hosts, target)\n        if observed != expected_host_key_sha256:\n            raise SSHTransportError("host_key_binding_mismatch")\n        self.target = target\n        self.known_hosts = known_hosts.resolve()\n        self.expected_host_key_sha256 = expected_host_key_sha256\n        self.runner = runner or Runner()\n        self.work_root = work_root\n        self._epoch = 0\n        self._directory: Path | None = None\n        self._control_path: Path | None = None\n        self._active = False\n\n    @property\n    def epoch(self) -> int:\n        return self._epoch\n\n    @property\n    def control_path(self) -> Path:\n        if self._control_path is None:\n            raise SSHTransportError("ssh_epoch_not_started")\n        return self._control_path\n\n    def _base_options(self) -> tuple[str, ...]:\n        return (\n            "-F",\n            "/dev/null",\n            "-o",\n            "StrictHostKeyChecking=yes",\n            "-o",\n            f"UserKnownHostsFile={self.known_hosts}",\n            "-o",\n            "GlobalKnownHostsFile=/dev/null",\n            "-o",\n            "HashKnownHosts=no",\n            "-o",\n            "IdentitiesOnly=yes",\n            "-o",\n            "IdentityAgent=none",\n        )\n\n    def _new_directory(self) -> Path:\n        root = self.work_root\n        if root is None:\n            root = Path("/private/tmp")\n            if not root.is_dir():\n                root = Path(tempfile.gettempdir())\n        if root.is_symlink() or not root.is_dir():\n            raise SSHTransportError("ssh_work_root_invalid")\n        directory = Path(tempfile.mkdtemp(prefix="n3w-f5-", dir=root))\n        os.chmod(directory, 0o700)\n        metadata = directory.stat()\n        if metadata.st_uid != os.geteuid() or stat.S_IMODE(metadata.st_mode) != 0o700:\n            shutil.rmtree(directory, ignore_errors=True)\n            raise SSHTransportError("ssh_work_directory_invalid")\n        return directory\n\n    def assert_master(self) -> None:\n        completed = self.runner.run(\n            (\n                "ssh",\n                "-S",\n                str(self.control_path),\n                "-O",\n                "check",\n                self.target,\n            ),\n            timeout=20,\n            check=False,\n        )\n        if completed.returncode != 0:\n            raise SSHTransportError("ssh_master_unavailable")\n\n    def start_epoch(self) -> dict[str, object]:\n        if self._active or self._directory is not None:\n            raise SSHTransportError("ssh_epoch_already_started")\n        directory = self._new_directory()\n        control = directory / "ctl"\n        if len(str(control)) > 90:\n            shutil.rmtree(directory, ignore_errors=True)\n            raise SSHTransportError("ssh_control_path_too_long")\n        self._directory = directory\n        self._control_path = control\n        try:\n            self.runner.run(\n                (\n                    "ssh",\n                    "-MNf",\n                    *self._base_options(),\n                    "-o",\n                    "ControlMaster=yes",\n                    "-o",\n                    "ControlPersist=no",\n                    "-o",\n                    f"ControlPath={control}",\n                    "-o",\n                    "PubkeyAuthentication=no",\n                    "-o",\n                    "PasswordAuthentication=yes",\n                    "-o",\n                    "KbdInteractiveAuthentication=yes",\n                    "-o",\n                    "PreferredAuthentications=keyboard-interactive,password",\n                    "-o",\n                    "NumberOfPasswordPrompts=1",\n                    self.target,\n                ),\n                timeout=180,\n                interactive=True,\n            )\n            self.assert_master()\n        except Exception:\n            self._cleanup_local()\n            raise\n        self._active = True\n        self._epoch += 1\n        return {\n            "status": "PASS",\n            "epoch": self._epoch,\n            "host_key_sha256": self.expected_host_key_sha256,\n            "password_persisted": False,\n            "new_login_key": False,\n        }\n\n    def _child_options(self) -> tuple[str, ...]:\n        self.assert_master()\n        return (\n            *self._base_options(),\n            "-o",\n            "ControlMaster=no",\n            "-o",\n            "ControlPersist=no",\n            "-o",\n            f"ControlPath={self.control_path}",\n            "-o",\n            "BatchMode=yes",\n            "-o",\n            "PubkeyAuthentication=no",\n            "-o",\n            "PasswordAuthentication=no",\n            "-o",\n            "KbdInteractiveAuthentication=no",\n            "-o",\n            "PreferredAuthentications=none",\n            "-o",\n            "ProxyCommand=/usr/bin/false",\n        )\n\n    def run_remote(\n        self,\n        argv: Sequence[str],\n        *,\n        timeout: float = 300,\n        check: bool = True,\n    ) -> subprocess.CompletedProcess[str]:\n        if not argv:\n            raise SSHTransportError("remote_command_empty")\n        return self.runner.run(\n            (\n                "ssh",\n                "-n",\n                *self._child_options(),\n                self.target,\n                shlex.join(tuple(argv)),\n            ),\n            timeout=timeout,\n            check=check,\n        )\n\n    def scp_to(\n        self,\n        source: Path,\n        remote_path: str,\n        *,\n        timeout: float = 1800,\n    ) -> subprocess.CompletedProcess[str]:\n        if source.is_symlink() or not source.is_file():\n            raise SSHTransportError("scp_source_invalid")\n        if not remote_path.startswith("/") or "\\n" in remote_path:\n            raise SSHTransportError("scp_remote_path_invalid")\n        return self.runner.run(\n            (\n                "scp",\n                *self._child_options(),\n                str(source),\n                f"{self.target}:{remote_path}",\n            ),\n            timeout=timeout,\n        )\n\n    def legacy_environment(self) -> dict[str, str]:\n        self.assert_master()\n        return {\n            "N3W_T1_SSH_CONTROL_PATH": str(self.control_path),\n            "N3W_T1_SSH_KNOWN_HOSTS": str(self.known_hosts),\n            "N3W_T1_SSH_TARGET": self.target,\n            "N3W_T1_SSH_CONNECTION_EPOCH": str(self._epoch),\n        }\n\n    def _managed_wrapper_script(self, executable: str) -> str:\n        return (\n            "#!/bin/sh\\n"\n            f"exec {shlex.quote(executable)} "\n            "-F /dev/null "\n            "-o StrictHostKeyChecking=yes "\n            "-o \\"UserKnownHostsFile=$N3W_T1_SSH_KNOWN_HOSTS\\" "\n            "-o GlobalKnownHostsFile=/dev/null "\n            "-o HashKnownHosts=no "\n            "-o IdentitiesOnly=yes "\n            "-o IdentityAgent=none "\n            "-o ControlMaster=no "\n            "-o ControlPersist=no "\n            "-o \\"ControlPath=$N3W_T1_SSH_CONTROL_PATH\\" "\n            "-o BatchMode=yes "\n            "-o PubkeyAuthentication=no "\n            "-o PasswordAuthentication=no "\n            "-o KbdInteractiveAuthentication=no "\n            "-o PreferredAuthentications=none "\n            "-o ProxyCommand=/usr/bin/false "\n            "\\"$@\\"\\n"\n        )\n\n    def managed_environment(\n        self,\n        base: dict[str, str] | None = None,\n    ) -> dict[str, str]:\n        self.assert_master()\n        if self._directory is None:\n            raise SSHTransportError("ssh_epoch_not_started")\n        wrapper_root = self._directory / "bin"\n        if wrapper_root.exists():\n            if (\n                wrapper_root.is_symlink()\n                or not wrapper_root.is_dir()\n                or wrapper_root.stat().st_uid != os.geteuid()\n                or stat.S_IMODE(wrapper_root.stat().st_mode) != 0o700\n            ):\n                raise SSHTransportError("ssh_wrapper_root_invalid")\n        else:\n            wrapper_root.mkdir(mode=0o700)\n        for name in ("ssh", "scp"):\n            executable = shutil.which(name)\n            if executable is None:\n                raise SSHTransportError(f"{name}_binary_missing")\n            wrapper = wrapper_root / name\n            expected = self._managed_wrapper_script(executable)\n            if wrapper.exists() or wrapper.is_symlink():\n                if (\n                    wrapper.is_symlink()\n                    or not wrapper.is_file()\n                    or wrapper.stat().st_uid != os.geteuid()\n                    or stat.S_IMODE(wrapper.stat().st_mode) != 0o700\n                    or wrapper.read_text(encoding="utf-8") != expected\n                ):\n                    raise SSHTransportError("ssh_wrapper_invalid")\n            else:\n                descriptor = os.open(\n                    wrapper,\n                    os.O_WRONLY\n                    | os.O_CREAT\n                    | os.O_EXCL\n                    | getattr(os, "O_NOFOLLOW", 0),\n                    0o700,\n                )\n                try:\n                    os.write(descriptor, expected.encode("utf-8"))\n                    os.fsync(descriptor)\n                finally:\n                    os.close(descriptor)\n                os.chmod(wrapper, 0o700)\n        environment = dict(os.environ if base is None else base)\n        environment.update(self.legacy_environment())\n        environment["N3W_T1_SSH_MANAGED_REQUIRED"] = "1"\n        original_path = environment.get("PATH", "")\n        environment["PATH"] = (\n            str(wrapper_root)\n            if not original_path\n            else f"{wrapper_root}{os.pathsep}{original_path}"\n        )\n        return environment\n\n    def _cleanup_local(self) -> None:\n        directory = self._directory\n        self._control_path = None\n        self._directory = None\n        self._active = False\n        if directory is not None and directory.exists():\n            shutil.rmtree(directory)\n\n    def close_epoch(self, *, expected_disconnect: bool = False) -> dict[str, object]:\n        if self._directory is None:\n            return {"status": "PASS", "session_closed": True, "epoch": self._epoch}\n        cleanup_error: Exception | None = None\n        if self._active:\n            try:\n                if not expected_disconnect:\n                    exited = self.runner.run(\n                        (\n                            "ssh",\n                            "-S",\n                            str(self.control_path),\n                            "-O",\n                            "exit",\n                            self.target,\n                        ),\n                        timeout=20,\n                        check=False,\n                    )\n                    if exited.returncode != 0:\n                        raise SSHTransportError("ssh_master_exit_failed")\n                checked = self.runner.run(\n                    (\n                        "ssh",\n                        "-S",\n                        str(self.control_path),\n                        "-O",\n                        "check",\n                        self.target,\n                    ),\n                    timeout=20,\n                    check=False,\n                )\n                if checked.returncode == 0:\n                    raise SSHTransportError("ssh_master_still_active")\n            except Exception as error:\n                cleanup_error = error\n        if cleanup_error is None:\n            try:\n                self._cleanup_local()\n            except Exception as error:\n                cleanup_error = error\n        if cleanup_error is not None:\n            raise SSHTransportError(\n                f"ssh_cleanup_failed:{type(cleanup_error).__name__}"\n            ) from cleanup_error\n        return {"status": "PASS", "session_closed": True, "epoch": self._epoch}\n\n    def start_post_reboot_epoch(self) -> dict[str, object]:\n        self.close_epoch(expected_disconnect=True)\n        return self.start_epoch()\n'

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--t1-ssh-target', required=True)
    parser.add_argument('--known-hosts', type=Path, required=True)
    parser.add_argument('--expected-host-key-sha256', required=True)
    parser.add_argument('--execute-authorized-u4-mount', action='store_true', required=True)
    args = parser.parse_args()
    evidence = Path.home()/'.n3w-evidence/kf147-u4-mount-recovery-20261111-01'
    os.umask(0o077)
    evidence.mkdir(parents=True, mode=0o700, exist_ok=False)
    scope = {'__name__': 'frozen_transport'}
    exec(compile(TRANSPORT, 'frozen_transport', 'exec'), scope)
    transport = None
    result = dict(status='STOP', remote_outcome='NOT_STARTED')
    try:
        transport = scope['SSHTransport'](target=args.t1_ssh_target,
            known_hosts=args.known_hosts.expanduser(), expected_host_key_sha256=args.expected_host_key_sha256)
        transport.start_epoch()
        result['remote_outcome'] = 'UNKNOWN'
        payload = base64.b64encode(json.dumps(PLAN).encode()).decode()
        done = transport.run_remote(['python3', '-B', '-c', REMOTE, payload], timeout=900, check=False)
        (evidence/'stdout.txt').write_text(done.stdout)
        (evidence/'stderr.txt').write_text(done.stderr)
        result = json.loads(done.stdout)
        result['rc'] = done.returncode
        if done.returncode != 0:
            result['status'] = 'STOP'
    except Exception as error:
        result['stop_code'] = type(error).__name__
    finally:
        if transport is not None:
            try:
                transport.close_epoch()
                result['ssh_master_cleanup'] = True
            except Exception:
                result['ssh_master_cleanup'] = False
                result['status'] = 'STOP'
        (evidence/'result.json').write_text(json.dumps(result, sort_keys=True, indent=2))
    print(json.dumps(result, sort_keys=True))
    return 0 if result.get('status') == 'U4_MOUNT_RECOVERY_PASS' else 2

if __name__ == '__main__':
    raise SystemExit(main())
